        if(record.receipt||existing?.receipt){try{const stock=await syncReceiptPurchases(record);if(stock.warnings.length)notify.warning(stock.warnings.join(' '));}catch(stockError){notify.warning(`Transaction saved, but grocery stock could not be synchronized: ${stockError.message}`)}}
        close();
