    {form.type!=='transfer'&&<div className="f-merchant-suggest"><MerchantLogo transaction={{title:form.title,merchantId:merchantSelection,type:form.type}} merchants={[...(data.merchantProfiles||[])]}/>{resolveMerchant({title:form.title,merchantId:merchantSelection,type:form.type},data.merchantProfiles)?<p className="f-help">Matched: <strong>{resolveMerchant({title:form.title,merchantId:merchantSelection,type:form.type},data.merchantProfiles)?.displayName}</strong></p>:<><p className="f-help">No saved merchant match. Unknown merchants use a letter badge.</p>{merchantSuggestions(form.title,data.merchantProfiles).length>0&&<div className="f-merchant-chips" aria-label="Merchant suggestions">{merchantSuggestions(form.title,data.merchantProfiles).map(item=><button type="button" className="f-button" key={item.id} onClick={()=>{setMerchantSelection(item.id);setNewMerchant(false)}}><MerchantLogo transaction={{title:item.displayName,merchantId:item.id,type:form.type}} merchants={[...(data.merchantProfiles||[])]}/>{item.displayName}</button>)}</div>}<button type="button" className="f-button" onClick={()=>setNewMerchant(value=>!value)}>{newMerchant?'Cancel merchant profile':'Create merchant profile'}</button></>}</div>}
