    <div className="f-between"><div><h2 className="text-3xl font-bold">Bank Connections</h2><p className="f-help">Read-only access for automatic bank sync. Transaction availability depends on your bank and its Open Banking service.</p></div></div>
    {error&&<p className="f-alert" role="alert">{error}</p>}{message&&<p className="f-item" role="status">{message}</p>}
    <section className="f-card"><h3>Connect a bank</h3><p className="f-help mt-2">Choose a supported GB personal banking service. The bank list comes from Enable Banking.</p><div className="f-actions mt-4"><select className="f-input" aria-label="Choose bank" value={selected} onChange={event=>setSelected(event.target.value)}><option value="">Select a bank</option>{aspsps.map(item=><option key={`${item.country}-${item.name}`} value={item.name}>{item.name}</option>)}</select><button className="f-primary" disabled={loading||!selected} onClick={()=>connect()}>{loading?'Opening bank authorizationâ€¦':'Connect bank'}</button></div>{loadingInstitutions&&!aspsps.length&&!error&&<p className="f-help mt-3">Loading available banksâ€¦</p>}</section>
