  const openDebt=id=>{const listKey=`finance-debt-scroll:${userId||'session'}`;try{sessionStorage.setItem(listKey,String(window.scrollY))}catch{};const params=new URLSearchParams(writeTransactionView(window.location.search,transactionViewRef.current));params.set('section','debts');window.history.pushState({},'',getAppHref(`/finance?${params.toString()}`));const href=getAppHref(`/finance/debt/${encodeURIComponent(id)}`);window.history.pushState({financeDebtList:true},'',href);setDebtId(id);setTabState('debts');window.scrollTo({top:0,behavior:'instant'})};
  const backToDebtList=()=>{if(window.history.state?.financeDebtList){window.history.back();return}const params=new URLSearchParams(writeTransactionView(window.location.search,transactionViewRef.current));params.set('section','debts');window.history.pushState({},'',getAppHref(`/finance?${params.toString()}`));setDebtId('');setTabState('debts')};
  const openDeduction=draft=>{setDeductionDraft(draft);setTab('automation')};
  const {confirm:confirmAction,dialog:confirmation}=useConfirmDialog();
