  const openTransfer=transferId=>{const transfer=(data?.sendMoneyHistory||[]).find(item=>item.id===transferId);if(transfer)setDialog({type:'sendMoneyTransfer',transferId})};
  const reverseTransfer=async(transferId,reason='')=>{try{await change(state=>{reverseSendMoney(state,transferId,today(),reason);return state},'Send Money transfer record reversed')}catch(error){notify.error(error.message)}};
  const openTransactionDetail=transaction=>{if(!transaction)return;transactionScrollPosition.current=window.scrollY;window.history.pushState({...window.history.state,financeTransactionDetail:transaction.id},'',window.location.href);setDialog({type:'transactionDetail',transactionId:transaction.id})};
