    try{const saved=await change(state=>{if(!markDebtPaymentUnpaid(state,transaction.id,today(),dialog.debtId))throw new Error('This payment could not be linked to that debt.');return state},'Debt payment marked unpaid and returned to due');if(saved)setDialog(null)}catch(error){notify.error(error.message)}
