  useEffect(()=>{if(!data||busy)return;const cutoff=Date.now()-6*60*60*1000;for(const connection of bankData.connections||[]){if(connection.status!=='connected'||autoSyncAttempted.current.has(connection.id))continue;autoSyncAttempted.current.add(connection.id);if(!connection.last_successful_sync_at||Date.parse(connection.last_successful_sync_at)<cutoff){bankDataProvider.sync(connection.id).then(result=>{if(!result.error)reload()}).catch(()=>reload())}}},[data,busy,bankData.connections]);
